create or replace view public.master_company_dashboard with (security_invoker=true) as with companies_scope as (select c.tenant_id,c.id company_id,coalesce(nullif(c.trade_name,''),c.legal_name) company_name,c.status company_status from public.companies c),hr as (select tenant_id,company_id,count(*) filter(where contract_status='active')::integer active_employees,coalesce(sum(pending_documents),0)::bigint pending_documents,coalesce(sum(pending_payroll_occurrences),0)::bigint pending_payroll_occurrences from public.hr_employee_status group by tenant_id,company_id),eng as (select tenant_id,company_id,work_count,updated_contract_value,measured_net,contract_balance,production_value,actual_revenue,outstanding_total,overdue_total,future_projected_revenue,alert_count,critical_alert_count from public.engineering_finance_company_executive),fin as (select * from public.finance_company_operational_summary),att as (select tenant_id,company_id,alert_count,critical_count,warning_count,attention_count,overdue_receivables,projected_cash_deficit from public.financial_attention_summary) select c.tenant_id,c.company_id,c.company_name,c.company_status,coalesce(fin.account_balance,0)::numeric(14,2) account_balance,coalesce(fin.payable_open,0)::numeric(14,2) payable_open,coalesce(fin.receivable_open,0)::numeric(14,2) receivable_open,coalesce(fin.overdue_open,0)::numeric(14,2) overdue_open,coalesce(fin.card_credit_limit,0)::numeric(14,2) card_credit_limit,coalesce(fin.card_committed,0)::numeric(14,2) card_committed,coalesce(fin.card_available,0)::numeric(14,2) card_available,coalesce(fin.card_open_statements,0)::numeric(14,2) card_open_statements,coalesce(fin.card_overdue_statements,0)::numeric(14,2) card_overdue_statements,coalesce(hr.active_employees,0) active_employees,coalesce(hr.pending_documents,0) pending_documents,coalesce(hr.pending_payroll_occurrences,0) pending_payroll_occurrences,coalesce(eng.work_count,0) work_count,coalesce(eng.updated_contract_value,0)::numeric(14,2) engineering_contract_value,coalesce(eng.measured_net,0)::numeric(14,2) engineering_measured_net,coalesce(eng.contract_balance,0)::numeric(14,2) engineering_contract_balance,coalesce(eng.production_value,0)::numeric(14,2) engineering_production_value,coalesce(eng.actual_revenue,0)::numeric(14,2) engineering_actual_revenue,coalesce(eng.outstanding_total,0)::numeric(14,2) engineering_outstanding,coalesce(eng.overdue_total,0)::numeric(14,2) engineering_overdue,coalesce(eng.future_projected_revenue,0)::numeric(14,2) engineering_future_revenue,greatest(coalesce(fin.attention_items,0),coalesce(att.alert_count,0)::integer,coalesce(eng.alert_count,0)::integer) attention_items,greatest(coalesce(att.critical_count,0)::integer,coalesce(eng.critical_alert_count,0)::integer) critical_items,coalesce(att.projected_cash_deficit,0)::numeric(14,2) projected_cash_deficit from companies_scope c left join fin on fin.tenant_id=c.tenant_id and fin.company_id=c.company_id left join hr on hr.tenant_id=c.tenant_id and hr.company_id=c.company_id left join eng on eng.tenant_id=c.tenant_id and eng.company_id=c.company_id left join att on att.tenant_id=c.tenant_id and att.company_id=c.company_id;
create or replace view public.master_company_monthly_dashboard with (security_invoker=true) as select b.tenant_id,b.company_id,b.competence_month,b.salary_projection,b.other_planned,b.total_planned_expense,b.actual_expense,b.actual_income,b.planned_remaining,b.configured_limits,b.limit_consumed,b.limit_remaining,b.engineering_projected_revenue,b.exceeded_limits,b.warning_limits,b.budget_execution_percent,b.budget_status,(b.actual_income-b.actual_expense)::numeric(14,2) actual_result,(b.engineering_projected_revenue-b.total_planned_expense)::numeric(14,2) projected_result from public.budget_dashboard_company b;
create or replace view public.master_attention_queue with (security_invoker=true) as select tenant_id,company_id,source_type,source_id,attention_date,description,status,amount from public.finance_operational_attention union all select tenant_id,company_id,'hr_employee'::text,employment_contract_id,current_date,full_name||' - pendência RH',operational_status,(pending_documents+pending_payroll_occurrences)::numeric from public.hr_employee_status where pending_documents>0 or pending_payroll_occurrences>0;
comment on view public.master_company_dashboard is 'Phase 11 master company dashboard foundation across Finance, HR and Engineering.';
comment on view public.master_company_monthly_dashboard is 'Phase 11 monthly planned versus actual company dashboard foundation.';
comment on view public.master_attention_queue is 'Phase 11 unified operational attention queue across Finance and HR.';